    {
        int[] nums = { 1, -2, 3, 0, -4, 5 };
        var posNums = nums.Where(n => n > 0).Select(r => r*2).
                      OrderByDescending(r=>r);
        Console.Write("The positive values in nums: ");
        foreach(int i in posNums)
        Console.Write(i + " ");
        Console.WriteLine();
        Console.ReadLine();
    }
}

